final class pollfd extends ffi.Struct {
  @ffi.Int()
  external int fd;

  @ffi.Short()
  external int events;

  @ffi.Short()
  external int revents;

  static ffi.Pointer<pollfd> $allocate(
    ffi.Allocator $allocator, {
    required int fd,
    required int events,
    required int revents,
  }) => $allocator<pollfd>()
    ..ref.fd = fd
    ..ref.events = events
    ..ref.revents = revents;
}

final class snd_midi_event extends ffi.Opaque {}

/// Sequencer event address
final class snd_seq_addr extends ffi.Struct {
  /// < Client id
  @ffi.UnsignedChar()
  external int client;

  /// < Port id
  @ffi.UnsignedChar()
  external int port;

  static ffi.Pointer<snd_seq_addr> $allocate(
    ffi.Allocator $allocator, {
    required int client,
    required int port,
  }) => $allocator<snd_seq_addr>()
    ..ref.client = client
    ..ref.port = port;
}

final class snd_seq_client_info_t extends ffi.Opaque {}

/// client types
sealed class snd_seq_client_type {
  /// < user client
  static const SND_SEQ_USER_CLIENT = 1;

  /// < kernel client
  static const SND_SEQ_KERNEL_CLIENT = 2;
}

/// Connection (subscription) between ports
final class snd_seq_connect extends ffi.Struct {
  /// < sender address
  external snd_seq_addr sender;

  /// < destination address
  external snd_seq_addr dest;
}

/// Controller event
final class snd_seq_ev_ctrl extends ffi.Struct {
  /// < channel number
  @ffi.UnsignedChar()
  external int channel;

  /// < reserved
  @ffi.Array.multi([3])
  external ffi.Array<ffi.UnsignedChar> unused;

  /// < control parameter
  @ffi.UnsignedInt()
  external int param;

  /// < control value
  @ffi.Int()
  external int value;
}

/// external stored data
@ffi.Packed(1)
final class snd_seq_ev_ext extends ffi.Struct {
  /// < length of data
  @ffi.UnsignedInt()
  external int len;

  /// < pointer to data (note: can be 64-bit)
  external ffi.Pointer<ffi.Void> ptr;

  static ffi.Pointer<snd_seq_ev_ext> $allocate(
    ffi.Allocator $allocator, {
    required int len,
    required ffi.Pointer<ffi.Void> ptr,
  }) => $allocator<snd_seq_ev_ext>()
    ..ref.len = len
    ..ref.ptr = ptr;
}

/// Note event
final class snd_seq_ev_note extends ffi.Struct {
  /// < channel number
  @ffi.UnsignedChar()
  external int channel;

  /// < note
  @ffi.UnsignedChar()
  external int note;

  /// < velocity
  @ffi.UnsignedChar()
  external int velocity;

  /// < note-off velocity; only for #SND_SEQ_EVENT_NOTE
  @ffi.UnsignedChar()
  external int off_velocity;

  /// < duration until note-off; only for #SND_SEQ_EVENT_NOTE
  @ffi.UnsignedInt()
  external int duration;

  static ffi.Pointer<snd_seq_ev_note> $allocate(
    ffi.Allocator $allocator, {
    required int channel,
    required int note,
    required int velocity,
    required int off_velocity,
    required int duration,
  }) => $allocator<snd_seq_ev_note>()
    ..ref.channel = channel
    ..ref.note = note
    ..ref.velocity = velocity
    ..ref.off_velocity = off_velocity
    ..ref.duration = duration;
}

/// queue timer control
final class snd_seq_ev_queue_control extends ffi.Struct {
  /// < affected queue
  @ffi.UnsignedChar()
  external int queue;

  /// < reserved
  @ffi.Array.multi([3])
  external ffi.Array<ffi.UnsignedChar> unused;

  /// < data value union
  external snd_seq_ev_queue_control_param param;
}

final class snd_seq_ev_queue_control_param extends ffi.Union {
  /// < affected value (e.g. tempo)
  @ffi.Int()
  external int value;

  /// < time
  external snd_seq_timestamp time;

  /// < sync position
  @ffi.UnsignedInt()
  external int position;

  /// < queue skew
  external snd_seq_queue_skew skew;

  /// < any data
  @ffi.Array.multi([2])
  external ffi.Array<ffi.UnsignedInt> d32;

  /// < any data
  @ffi.Array.multi([8])
  external ffi.Array<ffi.UnsignedChar> d8;
}

/// generic set of integers (3x32 bit)
final class snd_seq_ev_raw32 extends ffi.Struct {
  /// < 32 bit value
  @ffi.Array.multi([3])
  external ffi.Array<ffi.UnsignedInt> d;
}

/// generic set of bytes (12x8 bit)
final class snd_seq_ev_raw8 extends ffi.Struct {
  /// < 8 bit value
  @ffi.Array.multi([12])
  external ffi.Array<ffi.UnsignedChar> d;
}

/// UMP info change notify
final class snd_seq_ev_ump_notify extends ffi.Struct {
  /// < Client number
  @ffi.UnsignedChar()
  external int client;

  /// < Block number (optional)
  @ffi.UnsignedChar()
  external int block;

  static ffi.Pointer<snd_seq_ev_ump_notify> $allocate(
    ffi.Allocator $allocator, {
    required int client,
    required int block,
  }) => $allocator<snd_seq_ev_ump_notify>()
    ..ref.client = client
    ..ref.block = block;
}

/// Sequencer event
final class snd_seq_event extends ffi.Struct {
  /// < event type
  @ffi.UnsignedChar()
  external int type;

  /// < event flags
  @ffi.UnsignedChar()
  external int flags;

  /// < tag
  @ffi.UnsignedChar()
  external int tag;

  /// < schedule queue
  @ffi.UnsignedChar()
  external int queue;

  /// < schedule time
  external snd_seq_timestamp time;

  /// < source address
  external snd_seq_addr source;

  /// < destination address
  external snd_seq_addr dest;

  /// < event data...
  external snd_seq_event_data data;
}

/// Sequencer event data
final class snd_seq_event_data extends ffi.Union {
  /// < note information
  external snd_seq_ev_note note;

  /// < MIDI control information
  external snd_seq_ev_ctrl control;

  /// < raw8 data
  external snd_seq_ev_raw8 raw8;

  /// < raw32 data
  external snd_seq_ev_raw32 raw32;

  /// < external data
  external snd_seq_ev_ext ext;

  /// < queue control
  external snd_seq_ev_queue_control queue;

  /// < timestamp
  external snd_seq_timestamp time;

  /// < address
  external snd_seq_addr addr;

  /// < connect information
  external snd_seq_connect connect;

  /// < operation result code
  external snd_seq_result result;

  /// < UMP info change notification
  external snd_seq_ev_ump_notify ump_notify;
}

